import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import ArrowDropDownIcon from "@mui/icons-material/ArrowDropDown";
import { IconButton } from "@mui/material";
import shippingAPI from "../../services/shippingService";

export default function NDRManagement() {
  const navigate = useNavigate();
  const [ndrData, setNdrData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedNdr, setSelectedNdr] = useState(null);
  const [actionModal, setActionModal] = useState(false);
  const [actionData, setActionData] = useState({
    action: "",
    remark: ""
  });

  useEffect(() => {
    getNDRData();
  }, []);

  const getNDRData = async () => {
    try {
      const response = await shippingAPI.getNDRList({ per_page: 100 });
      if (response?.data?.status) {
        setNdrData(response.data.data || []);
      }
    } catch (error) {
      console.error("Error fetching NDR data:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleActionSubmit = async () => {
    if (!selectedNdr || !actionData.action) {
      alert("Please select an action");
      return;
    }

    try {
      const actions = [{
        awb_number: selectedNdr.awb_number,
        action: actionData.action,
        remark: actionData.remark
      }];

      const response = await shippingAPI.createNDRAction(actions);

      if (response?.data?.status) {
        alert("NDR action submitted successfully!");
        setActionModal(false);
        setSelectedNdr(null);
        setActionData({ action: "", remark: "" });
        getNDRData(); // Refresh data
      } else {
        alert("Failed to submit action: " + (response?.data?.message || "Unknown error"));
      }
    } catch (error) {
      console.error("Error submitting NDR action:", error);
      alert("Error submitting action: " + (error.response?.data?.message || error.message));
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    return new Date(dateString).toLocaleDateString();
  };

  const getActionColor = (action) => {
    const colors = {
      're_attempt': 'bg-blue-500',
      'return': 'bg-red-500',
      'dispose': 'bg-gray-500',
      'delivered': 'bg-green-500'
    };
    return colors[action] || 'bg-gray-500';
  };

  if (loading) {
    return (
      <div className="ndr-management">
        <h3 className="page_heading">NDR Management</h3>
        <div className="loading">Loading NDR data...</div>
      </div>
    );
  }

  return (
    <div className="ndr-management">
      <div className="ndr-management__header">
        <IconButton
          aria-label="Back"
          className="back__button"
          onClick={() => navigate(-1)}
        >
          <ArrowBackIcon />
        </IconButton>
        <h3 className="page_heading">NDR Management</h3>
      </div>

      <div className="ndr-management__content">
        {ndrData.length === 0 ? (
          <div className="no-data">
            <p>No NDR reports found</p>
          </div>
        ) : (
          <div className="ndr-table">
            <table>
              <thead>
                <tr>
                  <th>AWB Number <ArrowDropDownIcon /></th>
                  <th>Order ID <ArrowDropDownIcon /></th>
                  <th>Customer <ArrowDropDownIcon /></th>
                  <th>NDR Reason <ArrowDropDownIcon /></th>
                  <th>NDR Date <ArrowDropDownIcon /></th>
                  <th>Status <ArrowDropDownIcon /></th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {ndrData.map((ndr, index) => (
                  <tr key={index}>
                    <td>{ndr.awb_number}</td>
                    <td>{ndr.order_number || 'N/A'}</td>
                    <td>{ndr.customer_name || 'N/A'}</td>
                    <td>{ndr.ndr_reason || 'N/A'}</td>
                    <td>{formatDate(ndr.ndr_date)}</td>
                    <td>
                      <span className={`status-badge ${getActionColor(ndr.status)}`}>
                        {ndr.status || 'Pending'}
                      </span>
                    </td>
                    <td>
                      <button
                        className="button-red"
                        style={{ padding: '6px 12px', width: 'auto', fontSize: '13px' }}
                        onClick={() => {
                          setSelectedNdr(ndr);
                          setActionModal(true);
                        }}
                      >
                        Take Action
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Action Modal */}
      {actionModal && selectedNdr && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="modal-header">
              <h4>NDR Action for AWB: {selectedNdr.awb_number}</h4>
              <button
                className="modal-close"
                onClick={() => {
                  setActionModal(false);
                  setSelectedNdr(null);
                  setActionData({ action: "", remark: "" });
                }}
              >
                ×
              </button>
            </div>

            <div className="modal-body">
              <div className="ndr-details">
                <div className="detail-row">
                  <label>NDR Reason:</label>
                  <span>{selectedNdr.ndr_reason || 'N/A'}</span>
                </div>
                <div className="detail-row">
                  <label>Customer:</label>
                  <span>{selectedNdr.customer_name || 'N/A'}</span>
                </div>
                <div className="detail-row">
                  <label>Address:</label>
                  <span>{selectedNdr.customer_address || 'N/A'}</span>
                </div>
              </div>

              <div className="action-form">
                <div className="form-group">
                  <label>Action *</label>
                  <select
                    value={actionData.action}
                    onChange={(e) => setActionData(prev => ({ ...prev, action: e.target.value }))}
                    required
                  >
                    <option value="">Select Action</option>
                    <option value="re_attempt">Re-attempt Delivery</option>
                    <option value="return">Return to Sender</option>
                    <option value="dispose">Dispose Package</option>
                    <option value="delivered">Mark as Delivered</option>
                  </select>
                </div>

                <div className="form-group">
                  <label>Remark</label>
                  <textarea
                    value={actionData.remark}
                    onChange={(e) => setActionData(prev => ({ ...prev, remark: e.target.value }))}
                    placeholder="Add any remarks..."
                    rows={3}
                  />
                </div>
              </div>
            </div>

            <div className="modal-footer">
              <button
                className="btn btn-secondary"
                onClick={() => {
                  setActionModal(false);
                  setSelectedNdr(null);
                  setActionData({ action: "", remark: "" });
                }}
              >
                Cancel
              </button>
              <button
                className="button-red"
                onClick={handleActionSubmit}
              >
                Submit Action
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}